import React, { useEffect, useMemo, useRef, useState } from 'react'
import maplibregl from 'maplibre-gl'
import 'maplibre-gl/dist/maplibre-gl.css'
import { useApp } from '../state/AppContext'
import { CAMERAS, ZONES, ZONE_MAP, SITE_MAP, PALETTE } from '../data/catalog'
import { PlusIcon, MinusIcon } from './Icons'

/**
 * Operational Map — MapLibre GL JS industrial "digital twin".
 *
 * Tile-free dark style (no external tiles / API key / CSP exposure): the plant
 * is drawn entirely from GeoJSON layers (zone plots, 3D extruded asset blocks,
 * pipelines, restricted-zone glow) plus animated DOM markers (cameras, alerts,
 * gates) with rich popups. Pan / zoom / rotate / tilt are native MapLibre.
 *
 * Asset geometry is generated from a declarative SITE_LAYOUT table keyed by the
 * app's existing ZONE ids, and camera/alert positions come from the live app
 * data (CAMERAS + open events). Everything is expressed in lng/lat around a
 * configurable origin, so a real GIS feed from ServiceNow records can replace
 * the synthetic layout later with zero component changes.
 */

// ----- geo helpers -------------------------------------------------------
const ORIGIN: [number, number] = [55.08, 25.02] // synthetic Gulf refinery origin [lng,lat]
const LAT0 = (ORIGIN[1] * Math.PI) / 180
function off(eastM: number, northM: number): [number, number] {
    const dLat = northM / 111320
    const dLng = eastM / (111320 * Math.cos(LAT0))
    return [ORIGIN[0] + dLng, ORIGIN[1] + dLat]
}
// axis-aligned rectangle polygon centred at (ex,ey) meters, size (w,h) meters
function rect(ex: number, ey: number, w: number, h: number): [number, number][] {
    const hw = w / 2, hh = h / 2
    return [off(ex - hw, ey - hh), off(ex + hw, ey - hh), off(ex + hw, ey + hh), off(ex - hw, ey + hh), off(ex - hw, ey - hh)]
}

type Kind = 'process' | 'pump' | 'tank' | 'load' | 'cons' | 'rest'
interface Plot { ex: number; ey: number; w: number; h: number; kind: Kind }

// declarative plant layout (meters from origin). Keyed by the app's zone ids.
const SITE_LAYOUT: Record<string, Plot> = {
    'ZN-PROC': { ex: -520, ey: 300, w: 360, h: 300, kind: 'process' },
    'ZN-PUMP': { ex: -60, ey: 320, w: 300, h: 260, kind: 'pump' },
    'ZN-TANK': { ex: 420, ey: 300, w: 380, h: 320, kind: 'tank' },
    'ZN-LOAD': { ex: -420, ey: -260, w: 360, h: 260, kind: 'load' },
    'ZN-CONS': { ex: 40, ey: -280, w: 300, h: 240, kind: 'cons' },
    'ZN-REST': { ex: 470, ey: -260, w: 360, h: 260, kind: 'rest' },
}
const FALLBACK: Plot = { ex: 0, ey: 0, w: 260, h: 220, kind: 'cons' }
const plotFor = (zoneId: string): Plot => SITE_LAYOUT[zoneId] || FALLBACK

// 3D extruded sub-blocks per zone plot (deterministic). Absolute meters.
interface Block { ex: number; ey: number; w: number; d: number; h: number; color: string }
const KIND_BASE: Record<Kind, { color: string; hi: string }> = {
    process: { color: '#24485c', hi: '#2f6076' },
    pump: { color: '#34506a', hi: '#3f6a86' },
    tank: { color: '#2b5a52', hi: '#357066' },
    load: { color: '#50482f', hi: '#6a5f3c' },
    cons: { color: '#394f3c', hi: '#48654b' },
    rest: { color: '#5a2f36', hi: '#7a3d46' },
}
function blockDefs(p: Plot): Block[] {
    const base = KIND_BASE[p.kind]
    const out: Block[] = []
    const cols = 3, rows = 2
    const pad = Math.min(p.w, p.h) * 0.12
    const cw = (p.w - pad * 2) / cols
    const ch = (p.h - pad * 2) / rows
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
        const ex = p.ex - p.w / 2 + pad + cw * (c + 0.5)
        const ey = p.ey - p.h / 2 + pad + ch * (r + 0.5)
        const seed = Math.abs(Math.sin(ex * 12.9898 + ey * 78.233)) % 1
        let h: number
        switch (p.kind) {
            case 'process': h = 90 + seed * 150; break
            case 'tank': h = 55 + seed * 45; break
            case 'pump': h = 30 + seed * 35; break
            case 'load': h = 22 + seed * 22; break
            case 'cons': h = 30 + seed * 70; break
            default: h = 16 + seed * 18
        }
        out.push({ ex, ey, w: cw * 0.7, d: ch * 0.7, h: Math.round(h), color: seed > 0.6 ? base.hi : base.color })
    }
    return out
}

const SEV_COLOR: Record<string, string> = {
    low: PALETTE.vibrant, medium: PALETTE.amber, high: '#ff9a3d', critical: PALETTE.red,
}
const STATUS_COLOR: Record<string, string> = { online: PALETTE.cyan, degraded: PALETTE.amber, offline: '#6d8494' }
const OPEN = new Set(['active', 'acknowledged', 'investigating'])

// risk -> zone fill color
function zoneColor(risk: number): string {
    if (risk >= 180) return PALETTE.red
    if (risk >= 90) return '#ff9a3d'
    if (risk >= 30) return PALETTE.amber
    if (risk > 0) return PALETTE.vibrant
    return '#1f6b73'
}

// one-time keyframes for pulsing markers (self-contained, no theme.css edits)
let injected = false
function injectKeyframes() {
    if (injected || typeof document === 'undefined') return
    injected = true
    const s = document.createElement('style')
    s.textContent = `
@keyframes vicc-geo-pulse{0%{transform:scale(1);opacity:.9}70%{transform:scale(2.4);opacity:0}100%{opacity:0}}
@keyframes vicc-geo-sweep{to{transform:rotate(360deg)}}
.vicc-geo-marker{cursor:pointer;will-change:transform}
.maplibregl-popup.vicc-geo-pop .maplibregl-popup-content{background:rgba(9,20,31,.95);border:1px solid rgba(56,217,230,.5);border-radius:10px;padding:10px 12px;color:#f2f7f8;box-shadow:0 10px 34px rgba(0,0,0,.55);font-family:var(--vc-font,'Lato',sans-serif);min-width:190px}
.maplibregl-popup.vicc-geo-pop .maplibregl-popup-tip{border-top-color:rgba(56,217,230,.5)}
.maplibregl-popup.vicc-geo-pop .maplibregl-popup-close-button{color:#9fb4c0}`
    document.head.appendChild(s)
}

export default function OperationalMap() {
    const { filters, selectedCameraId, selectCamera, selectEvent, navigate, events } = useApp()
    const containerRef = useRef<HTMLDivElement>(null)
    const mapRef = useRef<maplibregl.Map | null>(null)
    const markersRef = useRef<maplibregl.Marker[]>([])
    const readyRef = useRef(false)
    const [ready, setReady] = useState(false)
    const [pitched, setPitched] = useState(true)

    const zones = useMemo(
        () => ZONES.filter((z) => filters.siteId === 'all' || z.siteId === filters.siteId),
        [filters.siteId],
    )
    const openEvents = useMemo(() => events.filter((e) => OPEN.has(e.status)), [events])
    const riskByZone = useMemo(() => {
        const m: Record<string, number> = {}
        openEvents.forEach((e) => (m[e.zoneId] = (m[e.zoneId] || 0) + e.riskScore))
        return m
    }, [openEvents])
    const alertByCam = useMemo(() => {
        const m: Record<string, number> = {}
        openEvents.forEach((e) => (m[e.cameraId] = (m[e.cameraId] || 0) + 1))
        return m
    }, [openEvents])

    // deterministic camera position inside its zone plot (uses cam.x/cam.y 0..100)
    const camLngLat = (camId: string): [number, number] => {
        const cam = CAMERAS.find((c) => c.id === camId)!
        const p = plotFor(cam.zoneId)
        const fx = (cam.x - 50) / 100 // -0.5..0.5
        const fy = (cam.y - 50) / 100
        return off(p.ex + fx * p.w * 0.72, p.ey - fy * p.h * 0.72)
    }

    // ----- build the plant GeoJSON (zones + 3D blocks + pipelines) --------
    const buildGeo = () => {
        const zoneFills: GeoJSON.Feature[] = []
        const zoneGlow: GeoJSON.Feature[] = []
        const blocks: GeoJSON.Feature[] = []
        zones.forEach((z) => {
            const p = plotFor(z.id)
            const risk = riskByZone[z.id] || 0
            zoneFills.push({ type: 'Feature', properties: { color: zoneColor(risk) }, geometry: { type: 'Polygon', coordinates: [rect(p.ex, p.ey, p.w, p.h)] } })
            zoneGlow.push({ type: 'Feature', properties: { color: z.id === 'ZN-REST' ? PALETTE.red : PALETTE.cyan }, geometry: { type: 'LineString', coordinates: rect(p.ex, p.ey, p.w, p.h) } })
            // 3D extruded asset blocks per zone kind
            const defs = blockDefs(p)
            defs.forEach((b) => blocks.push({ type: 'Feature', properties: { height: b.h, color: b.color }, geometry: { type: 'Polygon', coordinates: [rect(b.ex, b.ey, b.w, b.d)] } }))
        })
        // pipeline corridors connecting zone centroids in order
        const centroids = zones.map((z) => { const p = plotFor(z.id); return off(p.ex, p.ey) })
        const pipelines: GeoJSON.Feature[] = []
        for (let i = 0; i < centroids.length - 1; i++) {
            pipelines.push({ type: 'Feature', properties: {}, geometry: { type: 'LineString', coordinates: [centroids[i], centroids[i + 1]] } })
        }
        return { zoneFills, zoneGlow, blocks, pipelines }
    }

    // ----- init map once --------------------------------------------------
    useEffect(() => {
        injectKeyframes()
        if (!containerRef.current || mapRef.current) return
        const m = new maplibregl.Map({
            container: containerRef.current,
            style: {
                version: 8,
                sources: {},
                layers: [{ id: 'bg', type: 'background', paint: { 'background-color': '#07141f' } }],
            },
            center: ORIGIN,
            zoom: 14.2,
            pitch: 52,
            bearing: -18,
            antialias: true,
            attributionControl: false,
            dragRotate: true,
            maxZoom: 18,
            minZoom: 12,
        })
        mapRef.current = m
        m.on('load', () => {
            const { zoneFills, zoneGlow, blocks, pipelines } = buildGeo()
            m.addSource('zones', { type: 'geojson', data: { type: 'FeatureCollection', features: zoneFills } })
            m.addSource('glow', { type: 'geojson', data: { type: 'FeatureCollection', features: zoneGlow } })
            m.addSource('blocks', { type: 'geojson', data: { type: 'FeatureCollection', features: blocks } })
            m.addSource('pipes', { type: 'geojson', data: { type: 'FeatureCollection', features: pipelines } })

            // ground grid-ish zone fills
            m.addLayer({ id: 'zone-fill', type: 'fill', source: 'zones', paint: { 'fill-color': ['get', 'color'], 'fill-opacity': 0.14 } })
            // pipelines (dashed cyan corridors)
            m.addLayer({ id: 'pipe-line', type: 'line', source: 'pipes', paint: { 'line-color': PALETTE.cyan, 'line-width': 2, 'line-opacity': 0.5, 'line-dasharray': [2, 2] } })
            // glowing boundaries (wide blurred under-line + crisp top line)
            m.addLayer({ id: 'zone-glow', type: 'line', source: 'glow', paint: { 'line-color': ['get', 'color'], 'line-width': 6, 'line-blur': 6, 'line-opacity': 0.55 } })
            m.addLayer({ id: 'zone-edge', type: 'line', source: 'glow', paint: { 'line-color': ['get', 'color'], 'line-width': 1.4, 'line-opacity': 0.95 } })
            // 3D extruded asset blocks
            m.addLayer({ id: 'block-3d', type: 'fill-extrusion', source: 'blocks', paint: {
                'fill-extrusion-color': ['get', 'color'],
                'fill-extrusion-height': ['get', 'height'],
                'fill-extrusion-base': 0,
                'fill-extrusion-opacity': 0.88,
            } })
            readyRef.current = true
            setReady(true)
        })
        const ro = new ResizeObserver(() => m.resize())
        ro.observe(containerRef.current)
        return () => { ro.disconnect(); markersRef.current.forEach((mk) => mk.remove()); markersRef.current = []; m.remove(); mapRef.current = null; readyRef.current = false }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    // ----- refresh data-driven sources when app data changes --------------
    useEffect(() => {
        const m = mapRef.current
        if (!m || !readyRef.current) return
        const { zoneFills, zoneGlow, blocks, pipelines } = buildGeo()
        ;(m.getSource('zones') as maplibregl.GeoJSONSource)?.setData({ type: 'FeatureCollection', features: zoneFills })
        ;(m.getSource('glow') as maplibregl.GeoJSONSource)?.setData({ type: 'FeatureCollection', features: zoneGlow })
        ;(m.getSource('blocks') as maplibregl.GeoJSONSource)?.setData({ type: 'FeatureCollection', features: blocks })
        ;(m.getSource('pipes') as maplibregl.GeoJSONSource)?.setData({ type: 'FeatureCollection', features: pipelines })
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [zones, riskByZone])

    // ----- (re)build DOM markers: cameras + alerts + restricted gates -----
    useEffect(() => {
        const m = mapRef.current
        if (!m || !ready) return
        markersRef.current.forEach((mk) => mk.remove())
        markersRef.current = []

        const camsInView = CAMERAS.filter((c) => filters.siteId === 'all' || c.siteId === filters.siteId)
        camsInView.forEach((cam) => {
            const alerts = alertByCam[cam.id] || 0
            const color = STATUS_COLOR[cam.status]
            const sel = cam.id === selectedCameraId
            const el = document.createElement('div')
            el.className = 'vicc-geo-marker'
            el.innerHTML = `<div style="position:relative;width:16px;height:16px">
              ${alerts > 0 ? `<span style="position:absolute;inset:-4px;border-radius:50%;background:${PALETTE.red};opacity:.5;animation:vicc-geo-pulse 1.6s ease-out infinite"></span>` : ''}
              <span style="position:absolute;inset:0;border-radius:50%;background:${color};border:2px solid ${sel ? '#fff' : '#04161a'};box-shadow:0 0 10px ${color}"></span>
            </div>`
            const zone = ZONE_MAP[cam.zoneId]
            const pop = new maplibregl.Popup({ offset: 14, closeButton: false, className: 'vicc-geo-pop' }).setHTML(
                `<div style="font-weight:800;font-size:.82rem">${cam.id} · Camera</div>
                 <div style="color:#9fb4c0;font-size:.72rem;margin:2px 0 6px">${cam.name}</div>
                 <div style="display:flex;gap:6px;flex-wrap:wrap;font-size:.7rem">
                   <span style="color:${color}">● ${cam.status}</span>
                   <span style="color:#9fb4c0">${zone ? zone.name : cam.zoneId}</span>
                   <span style="color:${alerts ? PALETTE.red : PALETTE.vibrant}">${alerts} open alert${alerts === 1 ? '' : 's'}</span>
                 </div>`,
            )
            const mk = new maplibregl.Marker({ element: el }).setLngLat(camLngLat(cam.id)).setPopup(pop).addTo(m)
            el.addEventListener('click', () => { selectCamera(cam.id); m.easeTo({ center: camLngLat(cam.id), zoom: 15.2, duration: 700 }) })
            markersRef.current.push(mk)
        })

        // alert / incident markers (pulsing, colored by severity)
        openEvents.forEach((e) => {
            const color = SEV_COLOR[e.severity] || PALETTE.amber
            const el = document.createElement('div')
            el.className = 'vicc-geo-marker'
            const icon = e.category === 'fire' || e.category === 'smoke' ? '🔥' : e.category === 'intrusion' ? '⚠' : '◆'
            el.innerHTML = `<div style="position:relative;width:20px;height:20px;display:grid;place-items:center">
              <span style="position:absolute;inset:-6px;border-radius:50%;background:${color};opacity:.45;animation:vicc-geo-pulse 1.5s ease-out infinite"></span>
              <span style="position:absolute;inset:0;border-radius:50%;background:${color};border:1.5px solid #04161a;box-shadow:0 0 12px ${color};display:grid;place-items:center;font-size:10px;color:#04161a;font-weight:900">${icon}</span>
            </div>`
            const pop = new maplibregl.Popup({ offset: 16, closeButton: true, className: 'vicc-geo-pop' }).setHTML(
                `<div style="font-weight:800;font-size:.82rem;margin-bottom:2px">${e.title}</div>
                 <div style="display:flex;gap:6px;flex-wrap:wrap;font-size:.7rem;margin-bottom:6px">
                   <span style="color:${color};text-transform:capitalize">● ${e.severity}</span>
                   <span style="color:#9fb4c0">Risk ${e.riskScore}/100</span>
                   <span style="color:#9fb4c0;text-transform:capitalize">${e.status.replace('_', ' ')}</span>
                 </div>
                 <div style="font-size:.72rem;color:#cfe">${e.cameraId} · ${(ZONE_MAP[e.zoneId] || {}).name || e.zoneId}</div>
                 <button data-evt="${e.id}" style="margin-top:8px;width:100%;background:linear-gradient(135deg,#38d9e6,#0e7f8c);color:#04161a;border:none;border-radius:7px;padding:6px 10px;font-weight:800;cursor:pointer">Open in Safety</button>`,
            )
            // place near the event's camera, nudged so it doesn't sit exactly on the cam dot
            const base = camLngLat(e.cameraId)
            const mk = new maplibregl.Marker({ element: el }).setLngLat([base[0] + 0.00018, base[1] + 0.00018]).setPopup(pop).addTo(m)
            pop.on('open', () => {
                const btn = document.querySelector(`button[data-evt="${e.id}"]`)
                btn && btn.addEventListener('click', () => { selectEvent(e.id); navigate('safety') }, { once: true })
            })
            markersRef.current.push(mk)
        })

        // restricted-zone gate marker
        const rest = zones.find((z) => z.id === 'ZN-REST')
        if (rest) {
            const p = plotFor(rest.id)
            const el = document.createElement('div')
            el.className = 'vicc-geo-marker'
            el.innerHTML = `<div style="padding:2px 7px;border-radius:6px;background:rgba(255,102,115,.18);border:1px solid ${PALETTE.red};color:${PALETTE.red};font-size:.62rem;font-weight:800;letter-spacing:.5px;white-space:nowrap;box-shadow:0 0 12px rgba(255,102,115,.4)">⛔ RESTRICTED</div>`
            markersRef.current.push(new maplibregl.Marker({ element: el }).setLngLat(off(p.ex, p.ey + p.h / 2 + 40)).addTo(m))
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ready, filters.siteId, selectedCameraId, openEvents, alertByCam, zones])

    // keep selected camera centered
    useEffect(() => {
        const m = mapRef.current
        if (!m || !readyRef.current || !selectedCameraId) return
        if (!CAMERAS.some((c) => c.id === selectedCameraId)) return
        m.easeTo({ center: camLngLat(selectedCameraId), duration: 600 })
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedCameraId])

    const zoom = (d: number) => { const m = mapRef.current; m && m.easeTo({ zoom: Math.min(18, Math.max(12, m.getZoom() + d)), duration: 250 }) }
    const togglePitch = () => { const m = mapRef.current; if (!m) return; const np = pitched ? 0 : 52; m.easeTo({ pitch: np, bearing: np ? -18 : 0, duration: 600 }); setPitched(!pitched) }
    const resetView = () => { const m = mapRef.current; m && m.easeTo({ center: ORIGIN, zoom: 14.2, pitch: 52, bearing: -18, duration: 700 }) }

    const siteName = filters.siteId !== 'all' && SITE_MAP[filters.siteId] ? SITE_MAP[filters.siteId].name : 'All Sites'

    return (
        <div className="vicc-panel">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" /> Plant Overview Map <small>{siteName} · geospatial digital twin</small>
                </div>
                <div className="vicc-row" style={{ gap: 6 }}>
                    <button className="vicc-iconbtn" style={{ width: 30, height: 30 }} onClick={() => zoom(0.6)} aria-label="Zoom in"><PlusIcon size={14} /></button>
                    <button className="vicc-iconbtn" style={{ width: 30, height: 30 }} onClick={() => zoom(-0.6)} aria-label="Zoom out"><MinusIcon size={14} /></button>
                    <button className="vicc-btn vicc-btn--sm" onClick={togglePitch} aria-pressed={pitched}>{pitched ? '2D' : '3D'}</button>
                    <button className="vicc-btn vicc-btn--sm vicc-btn--ghost" onClick={resetView}>Reset</button>
                </div>
            </div>
            <div className="vicc-panel__body">
                <div className="vicc-map" style={{ position: 'relative' }}>
                    <div ref={containerRef} style={{ position: 'absolute', inset: 0, borderRadius: 10, overflow: 'hidden' }} />
                    {/* radar sweep overlay for wow factor (non-interactive) */}
                    <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', borderRadius: 10, overflow: 'hidden' }}>
                        <div style={{ position: 'absolute', top: '50%', left: '50%', width: '160%', height: '160%', transform: 'translate(-50%,-50%)', background: 'conic-gradient(from 0deg, rgba(56,217,230,0.16), transparent 32%)', animation: 'vicc-geo-sweep 7s linear infinite', mixBlendMode: 'screen' }} />
                    </div>
                    {!ready ? <div className="vicc-empty" style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center' }}>Initializing geospatial view…</div> : null}
                </div>
                <div className="vicc-map__legend">
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.cyan, background: PALETTE.cyan }} /> Camera</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.vibrant, background: PALETTE.vibrant }} /> Healthy</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.amber, background: PALETTE.amber }} /> Warning</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: '#ff9a3d', background: '#ff9a3d' }} /> Medium</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.red, background: PALETTE.red }} /> Critical</span>
                    <span style={{ marginLeft: 'auto', fontSize: '0.7rem', color: 'var(--vc-muted)' }}>
                        {CAMERAS.filter((c) => filters.siteId === 'all' || c.siteId === filters.siteId).length} cameras · {openEvents.length} open event(s) · drag to rotate · scroll to zoom
                    </span>
                </div>
            </div>
        </div>
    )
}
